import {
  DatePicker,
  DatePickerCalendar,
  DatePickerContent,
  DatePickerInput,
} from "@/registry/erbium/ui/date-picker";
import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";

export default function DatePickerExample() {
  return (
    <Field className="w-64">
      <FieldLabel htmlFor="date-picker-demo">Start date</FieldLabel>
      <DatePicker>
        <DatePickerInput id="date-picker-demo" />
        <DatePickerContent>
          <DatePickerCalendar />
        </DatePickerContent>
      </DatePicker>
      <FieldDescription>Type a date or press the down arrow to open the calendar.</FieldDescription>
    </Field>
  );
}
